<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue'
import {api} from './api'
import {subscribeActivity,connectionState} from './activity'
import {trackingLabel} from './gps'
import LiveTracking from './LiveTracking.vue'
import RecordEditor from './RecordEditor.vue'
const props=defineProps<{org:any,catalog:any[]}>(),emit=defineEmits(['context'])
const data=ref<any>(),error=ref(''),busy=ref(false),date=ref(''),followToday=ref(true),query=ref(''),filter=ref('all'),page=ref(1),alertPage=ref(1),tab=ref('overview'),selection=ref<any>(),resources=ref<any>(),resourcePage=ref(1),resourceQuery=ref(''),resourceAvailable=ref(false),map=ref<any>(),fullscreen=ref(false),editor=ref<any>(),record=ref<any>(),prefill=ref<any>(),assignment=ref<any>()
const request=(path:string,method='GET',body?:any)=>api(path,method,body,true,props.org.id)
let alive=true,unsubscribe:()=>void,timer:any,debounce:any,searchTimer:any,last=0,loading=false,again=false,generation=0,resourceGeneration=0,focus:HTMLElement|null=null
const resourceTab=computed(()=>['vehicles','drivers'].includes(tab.value))
const filterLabels:any={all:'Toutes',unassigned:'À affecter',planned:'Planifiées',upcoming:'À venir',active:'En cours',late:'En retard',completed:'Terminées',problems:'Problèmes'}
const stateLabels:any={available:'Disponible',in_mission:'En mission',booked:'Réservé',maintenance:'En maintenance',unavailable:'Indisponible',leave:'Congé',license:'Permis expiré',gps_lost:'GPS perdu'}
const severityLabels:any={critical:'Critique',attention:'Attention',information:'Information'}
const statusLabels:any={planned:'Planifiée',active:'En cours',completed:'Terminée',cancelled:'Annulée',confirmed:'À affecter'}
const kpis:any=[['total','Missions du jour','all'],['unassigned','À affecter','unassigned'],['planned','Planifiées','planned'],['active','En cours','active'],['completed','Terminées','completed'],['late','En retard','late'],['incidents','Incidents ouverts','alerts'],['gps_lost','GPS perdu','problems'],['available_vehicles','Véhicules disponibles','vehicles'],['available_drivers','Chauffeurs disponibles','drivers']]
function stamp(value:string){return value?new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short',timeZone:props.org.timezone||'UTC'}).format(new Date(value)):'Aucune position'}
async function load(){
 if(loading){again=true;return}loading=true;busy.value=!data.value;const revision=generation;last=performance.now()
 const params=new URLSearchParams({filter:filter.value,page:String(page.value),alert_page:String(alertPage.value),q:query.value});if(date.value&&!followToday.value)params.set('date',date.value);if(selection.value?.resource==='missions')params.set('selected_mission',selection.value.id)
 try{const result=await request('operations/center?'+params);if(alive&&revision===generation){data.value=result;if(followToday.value||!date.value)date.value=result.date;error.value='';if(selection.value?.resource==='missions'){const row=result.missions.results.find((x:any)=>x.id===selection.value.id);if(result.selection)selection.value=result.selection;else if(row)selection.value=row}}}catch(e:any){if(alive&&revision===generation){error.value=e.message;if(e.status===403){data.value=null;selection.value=null;resources.value=null;editor.value=null}}}finally{loading=false;busy.value=false;if(again&&alive){again=false;schedule()}}
}
function schedule(delay=500){if(!debounce)debounce=setTimeout(()=>{debounce=null;load();if(resourceTab.value)loadResources()},Math.max(delay,1000-(performance.now()-last)))}
function reload(){generation++;load()}
function chooseFilter(value:string){if(['alerts','vehicles','drivers'].includes(value)){tab.value=value;return}filter.value=value;page.value=1;tab.value='missions';reload()}
async function loadResources(){const revision=++resourceGeneration;const kind=tab.value==='drivers'?'drivers':'vehicles';const params=new URLSearchParams({kind,page:String(resourcePage.value),q:resourceQuery.value,available:resourceAvailable.value?'1':'0'});try{const result=await request('operations/resources?'+params);if(alive&&revision===resourceGeneration)resources.value=result}catch(e:any){if(alive&&revision===resourceGeneration)error.value=e.message}}
watch(tab,()=>{resourcePage.value=1;resources.value=null;if(resourceTab.value)loadResources()})
watch([resourcePage,resourceAvailable],loadResources)
function search(){clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page.value=1;alertPage.value=1;reload()},300)}
function searchResources(){clearTimeout(searchTimer);searchTimer=setTimeout(()=>{resourcePage.value=1;loadResources()},300)}
async function select(id:string){try{selection.value=await request('operations/missions/'+id);if(fullscreen.value)await toggleMap()}catch(e:any){error.value=e.message}}
function context(module:string,id:string){emit('context',{module,id})}
async function contact(row:any){try{const conversation=await request('employees/'+row.driver_id+'/contact','POST',{});emit('context',{conversation:conversation.id})}catch(e:any){error.value=e.message}}
async function edit(key:string,item:any=null,values:any={},assignmentContext:any=null){try{const schema=props.catalog.find(x=>x.key===key);if(!schema?.writable)throw new Error('Cette action est indisponible pour votre rôle ou cette entreprise.');record.value=item?await request(key+'/'+item.id):null;if(key==='missions'&&!item&&!values.departure){const start=new Date(Date.now()+300000);values={...values,departure:start.toISOString(),arrival:new Date(start.getTime()+3600000).toISOString()}}prefill.value=values;assignment.value=assignmentContext;editor.value=schema}catch(e:any){error.value=e.message}}
async function assign(row:any){const start=new Date(Date.now()+3600000),end=new Date(start.getTime()+3600000);await edit('missions',row.resource==='missions'?row:null,{origin:row.origin,destination:row.destination,departure:start.toISOString(),arrival:end.toISOString(),loaded_quantity:0},{[row.resource==='orders'?'order':'mission']:row.id,expected_updated_at:row.updated_at})}
async function alertAction(item:any){try{if(item.kind==='unassigned'){const row=await request('orders/'+item.object_id);await assign({...row,resource:'orders'})}else if(item.resource==='missions')await select(item.object_id);else context(item.resource,item.object_id)}catch(e:any){error.value=e.message}}
function incident(row:any){edit('incidents',null,{vehicle:row.vehicle_id,mission:row.id,occurred_at:new Date().toISOString(),title:'Incident '+row.reference})}
async function saved(){editor.value=null;selection.value=null;page.value=1;alertPage.value=1;reload();if(resourceTab.value)loadResources()}
async function toggleMap(){if(!fullscreen.value)focus=document.activeElement as HTMLElement;fullscreen.value=!fullscreen.value;await nextTick();if(fullscreen.value)document.querySelector<HTMLButtonElement>('.operations-map-close')?.focus();else focus?.focus()}
function keys(e:KeyboardEvent){if(e.key==='Escape'&&fullscreen.value)toggleMap()}
onMounted(()=>{load();unsubscribe=subscribeActivity(e=>{if(['operations','tracking','tracking_lifecycle','notification','resync'].includes(e.type))schedule(e.type==='tracking'?5000:500)});timer=setInterval(()=>{if(document.visibilityState==='visible'&&navigator.onLine)schedule()},30000);document.addEventListener('keydown',keys)})
onUnmounted(()=>{alive=false;unsubscribe?.();clearInterval(timer);clearTimeout(debounce);clearTimeout(searchTimer);document.removeEventListener('keydown',keys)})
defineExpose({refresh:reload})
</script>
<template>
 <section class="operations-center" aria-label="Centre d’exploitation">
  <header class="operations-toolbar"><div><strong>{{org.name}}</strong><p>{{connectionState}} · {{data?.timezone||org.timezone}} <span v-if="data">· Actualisé {{stamp(data.server_time)}}</span></p></div><label>Journée<input v-model="date" type="date" @change="followToday=false;page=1;alertPage=1;reload()"/></label><button class="secondary" @click="followToday=true;date='';page=1;alertPage=1;reload()">Aujourd’hui</button><button class="secondary" :disabled="busy" @click="reload">Actualiser</button></header>
  <div v-if="error" class="error-box" role="alert">{{error}} <button class="secondary" @click="reload">Réessayer</button></div>
  <p v-if="busy" role="status">Chargement de l’exploitation…</p>
  <template v-if="data">
   <p v-if="!data.current" class="info-box">Journée consultée : {{data.date}}. Les statuts reflètent la base actuelle. La carte, les alertes et les disponibilités restent ceux de maintenant.</p>
   <div class="operations-kpis"><button v-for="[key,label,target] in kpis" :key="key" :disabled="data.kpi[key]===null" @click="chooseFilter(target)"><strong>{{data.kpi[key]??'—'}}</strong><span>{{label}}</span></button></div>
   <div class="operations-quick"><button v-if="data.modules.orders" class="primary" @click="edit('orders')">+ Commande</button><button class="secondary" @click="edit('missions')">+ Mission</button><button v-if="data.modules.incidents" class="secondary" @click="edit('incidents')">Signaler un incident</button><small>Disponibilité sur les {{data.availability_minutes}} prochaines minutes · risques à {{data.risk_hours}} h</small></div>
   <nav class="operations-tabs" aria-label="Vues de l’exploitation"><button v-for="[key,label] in [['overview','Synthèse'],['map','Carte'],['missions','Missions'],['vehicles','Flotte'],['drivers','Chauffeurs'],['alerts','Alertes']]" :key="key" :aria-pressed="tab===key" @click="tab=key">{{label}}</button></nav>
   <div class="operations-layout" :class="{'operations-overview':tab==='overview'}">
    <section v-show="['overview','map'].includes(tab)" class="operations-map-panel" :class="{'operations-fullscreen':fullscreen}"><header><h2>Carte en direct</h2><button class="secondary operations-map-close" @click="toggleMap">{{fullscreen?'Fermer la carte':'Agrandir la carte'}}</button></header><LiveTracking ref="map" compact @mission="select"/></section>
    <aside v-if="selection" class="panel operations-selection"><header><h2>{{selection.reference}}</h2><button class="icon-btn" aria-label="Fermer la sélection" @click="selection=null">×</button></header><p>{{selection.origin}} → {{selection.destination}}</p><p>{{selection.plate}} · {{selection.driver}}</p><p>{{statusLabels[selection.status]}} · {{selection.status==='planned'?'GPS au démarrage':trackingLabel[selection.gps]||selection.gps}}</p><p>Départ {{stamp(selection.departure)}} · Arrivée {{stamp(selection.arrival)}}</p><p>Dernière position : {{stamp(selection.last_position_at)}}</p><div class="operations-actions"><button class="secondary" @click="map?.focusMission(selection.id);tab='map'">Centrer sur le véhicule</button><button class="secondary" @click="edit('missions',selection)">Voir mission / trajet</button><button class="secondary" @click="contact(selection)">Contacter chauffeur</button><button v-if="selection.customer_id&&data.modules.partners" class="secondary" @click="context('clients',selection.customer_id)">Voir client {{selection.customer}}</button><button v-if="selection.status==='planned'" class="secondary" @click="assign(selection)">Réaffecter</button><button v-if="data.modules.incidents" class="secondary" @click="incident(selection)">Signaler incident</button></div></aside>
    <section v-if="['overview','missions'].includes(tab)" class="panel operations-missions"><header><h2>Missions · {{data.missions.count}}</h2><input v-model="query" type="search" aria-label="Rechercher dans l’exploitation" placeholder="Mission, client, chauffeur, plaque…" @input="search"/></header><nav class="operations-filters" aria-label="Filtres missions"><button v-for="(label,key) in filterLabels" :aria-pressed="filter===String(key)" @click="chooseFilter(String(key))">{{label}}</button></nav><p v-if="!data.missions.results.length">Aucune mission ou commande pour ce filtre.</p><article v-for="row in data.missions.results" :key="row.id" class="operations-card" :data-operation="row.id"><header><button class="record-link" @click="row.resource==='missions'?select(row.id):edit('orders',row)">{{row.reference}}</button><span class="status">{{statusLabels[row.status]}}</span></header><p>{{row.customer||'Transport interne / voyageurs'}} · {{row.origin}} → {{row.destination}}</p><p v-if="row.resource==='missions'">{{row.plate}} · {{row.driver}}<br/>{{stamp(row.departure)}} → {{stamp(row.arrival)}}<br/>{{row.status==='planned'?'GPS au démarrage':trackingLabel[row.gps]||row.gps}} · Dernière position {{stamp(row.last_position_at)}}</p><p v-else>Prévue le {{row.planned_date}}</p><p v-if="row.late||row.resource_problem||row.delivery_problem" class="danger-text">{{row.late?'Horaire dépassé. ':''}}{{row.resource_problem?'Ressource indisponible. ':''}}{{row.delivery_problem?'Livraison à vérifier.':''}}</p><div class="operations-actions"><button v-if="row.resource==='orders'||row.status==='planned'" class="secondary" @click="assign(row)">{{row.resource==='orders'?'Affecter':'Réaffecter'}}</button><button v-if="row.resource==='missions'" class="secondary" @click="select(row.id)">Voir détails</button><button v-if="row.resource==='missions'" class="text-btn" @click="contact(row)">Contacter chauffeur</button><button v-if="row.customer_id&&data.modules.partners" class="text-btn" @click="context('clients',row.customer_id)">Voir client</button></div></article><footer class="operations-pages"><button class="secondary" :disabled="page<=1" @click="page--;reload()">Précédente</button><span>{{data.missions.page}} / {{data.missions.pages}}</span><button class="secondary" :disabled="page>=data.missions.pages" @click="page++;reload()">Suivante</button></footer></section>
    <section v-if="['overview','alerts'].includes(tab)" class="panel operations-alerts"><h2>Alertes actuelles · {{data.alerts.count}}</h2><p v-if="!data.alerts.results.length">Aucune alerte opérationnelle.</p><article v-for="item in data.alerts.results" :key="item.key" class="operations-card" :data-severity="item.severity"><strong>{{severityLabels[item.severity]}} · {{item.title}}</strong><p>{{item.label}} · {{stamp(item.due_sort)}}</p><button class="secondary" @click="alertAction(item)">{{item.kind==='unassigned'?'Affecter':'Voir / traiter'}}</button></article><footer class="operations-pages"><button class="secondary" :disabled="alertPage<=1" @click="alertPage--;reload()">Alertes précédentes</button><span>{{data.alerts.page}} / {{data.alerts.pages}}</span><button class="secondary" :disabled="alertPage>=data.alerts.pages" @click="alertPage++;reload()">Alertes suivantes</button></footer></section>
    <section v-if="resourceTab" class="panel operations-resources"><header><h2>{{tab==='drivers'?'Chauffeurs':'Flotte'}}</h2><input v-model="resourceQuery" type="search" aria-label="Rechercher une ressource" placeholder="Nom ou plaque…" @input="searchResources"/><label class="checkbox-label"><input v-model="resourceAvailable" type="checkbox"/>Disponibles maintenant</label></header><p v-if="!resources" role="status">Chargement des ressources…</p><template v-else><p class="operations-resource-summary"><span v-for="(value,key) in resources.summary" :key="key">{{stateLabels[key]||({total:"Total",in_mission:"En route"} as any)[key]||key}} : {{value}} · </span></p><p v-if="!resources.count">Aucune ressource pour cette recherche.</p><article v-for="row in resources.results" :key="row.id" class="operations-card"><header><strong>{{row.label}}</strong><span class="status">{{stateLabels[row.state]}}</span></header><p v-if="row.current_mission">{{row.current_reference}} · {{row.current_driver||row.current_vehicle}} <button class="text-btn" @click="select(row.current_mission)">Voir mission</button></p><p v-if="row.next_mission">Prochaine : {{row.next_reference}} {{row.next_departure?stamp(row.next_departure):''}} <button class="text-btn" @click="select(row.next_mission)">Voir mission</button></p><p v-if="tab==='vehicles'&&row.current_mission">{{trackingLabel[row.gps]}} · Dernière position {{stamp(row.last_position_at)}}</p><button v-if="tab==='drivers'" class="secondary" @click="contact({driver_id:row.id})">Contacter</button><button v-if="row.intervention&&data.modules.maintenance" class="secondary" @click="context('maintenance',row.intervention)">Voir intervention</button><button class="text-btn" @click="context(tab==='drivers'?'employees':'vehicles',row.id)">Voir fiche</button></article><footer class="operations-pages"><button class="secondary" :disabled="resourcePage<=1" @click="resourcePage--">Précédente</button><span>{{resourcePage}} · {{resources.count}} ressources</span><button class="secondary" :disabled="!resources.next" @click="resourcePage++">Suivante</button></footer></template></section>
   </div>
   <section v-if="tab==='overview'" class="panel operations-activity"><h2>Activité récente</h2><p v-if="!data.activity.length">Aucune activité récente.</p><button v-for="item in data.activity" :key="item.id" class="text-btn" @click="context(item.resource,item.object_id)">{{stamp(item.created_at)}} · {{item.label}} {{item.reference}}</button></section>
  </template>
  <RecordEditor v-if="editor" :schema="editor" :record="record" :prefill="prefill" :assignment="assignment" :available-resources="editor.key==='missions'&&!record" :scope="org.id" :currency="org.currency" :admin="['owner','admin'].includes(org.role)" @close="editor=null" @saved="saved"/>
 </section>
</template>
<style scoped>
.operations-center{min-width:0}.operations-toolbar,.operations-quick,.operations-actions,.operations-pages,.operations-map-panel>header,.operations-card>header,.operations-selection>header{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.operations-toolbar{justify-content:space-between}.operations-toolbar p{font-size:12px;color:#526176}.operations-toolbar label{max-width:180px}.operations-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(125px,1fr));gap:10px;margin:18px 0}.operations-kpis button{text-align:left;padding:14px;border:1px solid #dce5ef;border-radius:12px;background:white;color:#153551;min-height:86px}.operations-kpis strong{display:block;font-size:25px}.operations-kpis span{font-size:12px}.operations-quick{margin:16px 0}.operations-quick small{color:#526176}.operations-tabs,.operations-filters{display:flex;gap:6px;overflow-x:auto;padding:8px 0}.operations-tabs button,.operations-filters button{flex-shrink:0;min-height:44px;padding:8px 14px;border:1px solid #dce5ef;border-radius:8px;background:white}.operations-tabs [aria-pressed=true],.operations-filters [aria-pressed=true]{background:#095cad;color:white;border-color:#095cad}.operations-layout{display:grid;gap:16px;margin:12px 0}.operations-map-panel{min-width:0}.operations-map-panel>header{justify-content:space-between}.operations-map-panel :deep(.live-tracking){padding:12px;margin-top:10px}.operations-missions,.operations-alerts,.operations-resources,.operations-selection,.operations-activity{padding:18px;min-width:0}.operations-missions>header,.operations-resources>header{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.operations-missions input,.operations-resources input[type=search]{max-width:350px;flex:1;min-width:180px}.operations-card{padding:16px 0;border-bottom:1px solid #e2e8f0;overflow-wrap:anywhere}.operations-card>header{justify-content:space-between}.operations-card p{font-size:13px;line-height:1.7;margin:9px 0}.operations-card[data-severity=critical]{border-left:4px solid #ad3444;padding-left:12px}.operations-card[data-severity=attention]{border-left:4px solid #ac6900;padding-left:12px}.operations-pages{justify-content:space-between;margin-top:14px}.operations-selection{border:2px solid #095cad}.operations-selection p{line-height:1.7;overflow-wrap:anywhere}.operations-activity .text-btn{display:block;margin:10px 0;text-align:left}.operations-fullscreen{position:fixed;inset:0;z-index:1300;background:#f5f8fc;padding:calc(16px + env(safe-area-inset-top)) 16px calc(16px + env(safe-area-inset-bottom));display:flex;flex-direction:column}.operations-fullscreen :deep(.live-tracking){flex:1;display:flex;flex-direction:column;min-height:0}.operations-fullscreen :deep(.tracking-map){height:auto!important;flex:1;min-height:200px}.operations-center button{min-height:44px}.operations-actions .secondary{font-size:12px}@media(min-width:1000px){.operations-overview{grid-template-columns:minmax(0,1.4fr) minmax(0,1fr)}.operations-overview .operations-map-panel{grid-column:1}.operations-overview .operations-selection{grid-column:2}.operations-overview .operations-missions{grid-column:1}.operations-overview .operations-alerts{grid-column:2}}@media(max-width:600px){.operations-toolbar{gap:8px}.operations-toolbar>div{width:100%}.operations-kpis{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.operations-quick button{flex:1}.operations-missions,.operations-alerts,.operations-resources,.operations-selection{padding:12px}.operations-actions{gap:8px}.operations-pages{gap:6px}.operations-pages button{padding:8px;font-size:12px}.operations-fullscreen{padding-left:8px;padding-right:8px}}
</style>
